using Mutagen.Bethesda.Plugins.Binary.Headers;
using Mutagen.Bethesda.Plugins.Meta;
using Mutagen.Bethesda.Starfield;
using Shouldly;
using Xunit;
using static Mutagen.Bethesda.UnitTests.Plugins.Records.Starfield.StarfieldTestRecords;

namespace Mutagen.Bethesda.UnitTests.Plugins.Records.Starfield;

// Scene-level subrecords Mutagen kept raw or named after their signatures get xEdit's names and types:
// SCPI Priority (UInt16), JNAM Override Subtitle Priority (the INFO subtitle priority enum, Low 0 ... Force 3),
// the Speech Challenge Data (SCSP marker, SPMA/SPEX scene lists, SPRK Risk enum, SPRW Reward, SPRP/SPDF flags,
// SPKW/SPKY keyword lists, SPPK perks), BOLV as a marker and DEVT Show One Dialogue Track.
// Each test reads a whole scene from Starfield.esm with both readers and writes it back byte for byte.
public class SceneSpeechChallengeTests
{
    private static IEnumerable<ISceneGetter> Read(string hex)
        => ReadBoth<ISceneGetter>(Record("SCEN", Hex(hex)), f => Scene.CreateFromBinary(f), (s, p) => SceneBinaryOverlay.SceneFactory(s, p));

    private static void WritesBack(ISceneGetter scen, string hex)
    {
        var written = GameConstants.Starfield.MajorRecord(Write(w => scen.WriteToBinary(w)));
        written.Content.ToArray().ShouldBe(Hex(hex));
    }

    // SC_ACC_INF_DEF_KeepConfidential (29A8CA:Starfield.esm)
    private const string KeepConfidential = "";

    // Rad01_Convo_Ch_Intimidating_H7 (060132:Starfield.esm)
    private const string Intimidating = "";

    // RI02_200_Zola_SC_VisionMisc03Scene (25D694:Starfield.esm)
    private const string Zola = "";

    // City_NA_Well01_002_Louisa_Box01Nearby (24F4F7:Starfield.esm)
    private const string Louisa = "";

    // MQ101_016_KreetOrbitScene (063800:Starfield.esm)
    private const string Kreet = "";

    [Fact]
    public void KeepConfidential_PriorityAndChallengeFlags()
    {
        foreach (var scen in Read(KeepConfidential))
        {
            scen.Priority.ShouldBe((ushort)500);
            scen.IsSpeechChallenge.ShouldBeTrue();
            scen.ChallengeRisk.ShouldBe(Scene.SpeechChallengeRisk.Easy);
            scen.ChallengeReward.ShouldBe(2u);
            scen.ChallengeRepeatable.ShouldBeTrue();
            scen.ChallengeDefault.ShouldBeTrue();
            scen.SPPQ.ShouldBeTrue();
            scen.ChallengeOrKeywords!.Select(k => k.FormKey.ID).ShouldBe(new[] { 0x013B28u, 0x013B29u });
            scen.ChallengeAndKeywords.ShouldBeNull();
            scen.BOLV.ShouldBeTrue();
            scen.ShowOneDialogueTrack.ShouldBeFalse();
            scen.OverrideSubtitlePriority.ShouldBeNull();
            WritesBack(scen, KeepConfidential);
        }
    }

    [Fact]
    public void Intimidating_MandatoryNextAndPerks()
    {
        foreach (var scen in Read(Intimidating))
        {
            scen.Priority.ShouldBeNull();
            scen.IsSpeechChallenge.ShouldBeTrue();
            scen.MandatoryNextChallenges!.Select(k => k.FormKey.ID).ShouldBe(new[] { 0x13E069u });
            scen.ChallengeRisk.ShouldBe(Scene.SpeechChallengeRisk.Hard);
            scen.ChallengeReward.ShouldBe(7u);
            scen.ChallengeRepeatable.ShouldBeFalse();
            scen.ChallengeDefault.ShouldBeFalse();
            scen.ChallengeAndKeywords!.Select(k => k.FormKey.ID).ShouldBe(new[] { 0x13E06Au });
            scen.ChallengePerks!.Select(k => k.FormKey.ID).ShouldBe(new[] { 0x2C59DEu });
            WritesBack(scen, Intimidating);
        }
    }

    [Fact]
    public void Zola_ExcludedChallenges()
    {
        foreach (var scen in Read(Zola))
        {
            scen.MandatoryNextChallenges!.Select(k => k.FormKey.ID).ShouldBe(new[] { 0x25D693u, 0x25D691u, 0x25D692u, 0x25D69Fu });
            scen.ExcludedChallenges!.Count.ShouldBe(15);
            scen.ChallengeRisk.ShouldBe(Scene.SpeechChallengeRisk.Hard);
            scen.ChallengeReward.ShouldBe(5u);
            scen.ChallengeDefault.ShouldBeTrue();
            WritesBack(scen, Zola);
        }
    }

    [Fact]
    public void Louisa_ForcedSubtitles()
    {
        foreach (var scen in Read(Louisa))
        {
            scen.Priority.ShouldBe((ushort)60);
            scen.OverrideSubtitlePriority.ShouldBe(DialogResponses.SubtitlePriorityLevel.Force);
            scen.IsSpeechChallenge.ShouldBeFalse();
            scen.ChallengeRisk.ShouldBeNull();
            WritesBack(scen, Louisa);
        }
    }

    [Fact]
    public void Kreet_ShowOneDialogueTrack()
    {
        foreach (var scen in Read(Kreet))
        {
            scen.ShowOneDialogueTrack.ShouldBeTrue();
            scen.BOLV.ShouldBeFalse();
            WritesBack(scen, Kreet);
        }
    }
}
